mncs 0.5;

module mncs.core.status.v1;

enum Status { PASS, FAIL, UNKNOWN }

fn dominate(left: Status, right: Status) -> (result: Status) {
    return match left {
        Status::FAIL => Status::FAIL,
        _ => right,
    };
}

mncs 0.5;

module mncs.core.logic.v1;

use mncs.core.status.v1;

fn require(left: Status, right: Status) -> (result: Status) {
    return dominate(left, right);
}
